+export const verifySessionToken = (token: string): Session | null => {
+  const session = verifyToken(token);
+  if (!session) return null;
+  return {
+    id: session.sessionId,
+    userId: session.userId,
+    revokedAt: null,
+  };
+};
+
+export const validateSessionToken = async (
+  token: string,
+): Promise<Session | null> => {
+  const session = verifySessionToken(token);
+  if (!session) return null;
+
+  const result = await pool.query(
+    "SELECT revoked_at FROM sessions WHERE id = $1",
+    [session.id],
+  );
+  const row = result.rows[0];
+  if (row !== undefined && row.revoked_at !== null) return null;
+
+  return session;
+};
+
 export const revokeSession = async (id: string): Promise<void> => {
   await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
 };
+
+export const createSignedToken = (
+  sessionId: string,
+  userId: string,
+): string => {
+  const now = Date.now();
+  const expiresAt = now + 24 * 60 * 60 * 1000; // 24 hours
+  return issueToken({
+    sessionId,
+    userId,
+    issuedAt: now,
+    expiresAt,
+  });
+};
