@@ -0,0 +1,44 @@
+import { createHmac } from "crypto";
+
+export interface SignedSession {
+  sessionId: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+const key = process.env.SESSION_SIGNING_KEY || "development-key";
+
+const encode = (data: object): string => {
+  return Buffer.from(JSON.stringify(data)).toString("base64url");
+};
+
+const decode = (data: string): object => {
+  return JSON.parse(Buffer.from(data, "base64url").toString("utf-8"));
+};
+
+const sign = (data: string): string => {
+  return createHmac("sha256", key).update(data).digest("base64url");
+};
+
+export const issueToken = (session: SignedSession): string => {
+  const payload = encode(session);
+  const signature = sign(payload);
+  return `${payload}.${signature}`;
+};
+
+export const verifyToken = (token: string): SignedSession | null => {
+  const [payload, signature] = token.split(".");
+  if (!payload || !signature) return null;
+
+  const expectedSignature = sign(payload);
+  if (signature !== expectedSignature) return null;
+
+  try {
+    const data = decode(payload) as SignedSession;
+    if (Date.now() > data.expiresAt) return null;
+    return data;
+  } catch {
+    return null;
+  }
+};
